<script>
  import Modal from './CockpitModal.svelte'
  import { onMount } from 'svelte'
  import { apiGet, apiPut } from './api.js'
  import { url, csv, LEVEL } from './cockpit.js'
  let { tenant } = $props()
  let data = $state(null), loading = $state(false), error = $state(''), q = $state(''), level = $state('all'), expanded = $state(null), review = $state(null), note = $state(''), saving = $state(false)
  let apps = $derived((data?.apps || []).filter(a => !q || `${a.name} ${a.appId}`.toLowerCase().includes(q.toLowerCase())).filter(a => level === 'all' || (level === 'reviewed' ? a.reviewed : level === 'unknown' ? a.gap : a.level === level)))
  async function load() { loading = true; error = ''; try { data = await apiGet(url(tenant.id,'apps')) } catch(e) { error = e.message }; loading = false }
  async function save() { saving = true; try { const r = await apiPut(url(tenant.id,`apps/${encodeURIComponent(review.id)}/review`), { note }); review.reviewed = r.review; review = null } catch(e) { error = e.message }; saving = false }
  onMount(load)
</script>
<div class="cp-head"><div><h2>App-Registrierungen & Unternehmensanwendungen</h2><p>{tenant.name} · Erteilte Berechtigungen und Risikoanalyse</p></div><div class="cp-actions"><button class="btn btn-secondary" onclick={() => csv('App-Risiken',['Name','App ID','Risiko','Score','Datenlücke'],apps.map(a => [a.name,a.appId,LEVEL[a.level],a.score,a.gap]))}>CSV Export</button><button class="btn btn-primary" onclick={load} disabled={loading}>{loading ? 'Prüfe Berechtigungen…' : 'Jetzt synchronisieren'}</button></div></div>
<div class="cp-note">Bewertung der erteilten App- und delegierten Rechte: kritische Rechte 100 Punkte, schreibende Rechte 40, tenantweite Leserechte 10, übrige 2. Die höchste Rechteklasse bestimmt die Risikostufe. Das ist eine Priorisierung zur Prüfung. Eine markierte Prüfung ändert die erteilten Rechte nicht.</div>
{#if error}<div class="cp-note cp-gaps" role="alert">{error}</div>{/if}
{#if data?.gaps?.length}<div class="cp-note cp-gaps">{data.gaps.map(g => g.source + ': ' + g.message).join(' · ')}</div>{/if}
<div class="cp-kpis">{#each Object.entries(LEVEL) as [id,label]}<button class="cp-kpi" class:active={level === id} onclick={() => level = level === id ? 'all' : id}><span>{label}</span><strong>{data?.apps?.filter(a => a.level === id && !a.gap).length ?? '—'}</strong></button>{/each}</div>
<div class="cp-panel cp-toolbar"><input type="search" bind:value={q} placeholder="Anwendungen durchsuchen…" aria-label="Anwendungen durchsuchen"/><select bind:value={level} aria-label="Risiko filtern"><option value="all">Alle Risikostufen</option>{#each Object.entries(LEVEL) as [id,label]}<option value={id}>{label}</option>{/each}<option value="unknown">Mit Datenlücke</option><option value="reviewed">Als geprüft markiert</option></select><span class="cp-sub">{apps.length} Anwendungen</span></div>
<div class="cp-table-wrap"><table><thead><tr><th>Anwendung</th><th>Risikostufe</th><th>Score</th><th>Berechtigungen</th><th>Prüfung</th></tr></thead><tbody>{#each apps as a}<tr><td><button class="btn btn-secondary" onclick={() => expanded = expanded === a.id ? null : a.id}>{expanded === a.id ? '−' : '+'} {a.name}</button><small>{a.appId}</small></td><td><span class="cp-badge {a.gap ? '' : a.level}">{a.gap ? 'Unvollständig' : LEVEL[a.level]}</span></td><td>{a.score}</td><td>{a.factors.length}</td><td><button class="btn btn-secondary" onclick={() => { review = a; note = a.reviewed?.note || '' }}>{a.reviewed ? 'Geprüft ✓' : 'Prüfung dokumentieren'}</button></td></tr>{#if expanded === a.id}<tr><td colspan="5"><div class="cp-app-details">{#if a.gap}<p class="cp-crit">Datenlücke: {a.gap}</p>{/if}{#each a.factors as f}<span class="cp-badge {f.level}">{f.name} · {f.weight}</span>{:else}<span>Keine auflösbaren erteilten Rechte.</span>{/each}{#if a.reviewed}<p>Prüfung: {a.reviewed.note}</p>{/if}</div></td></tr>{/if}{:else}<tr><td colspan="5">{loading ? 'Anwendungen werden geprüft…' : 'Keine Anwendungen verfügbar.'}</td></tr>{/each}</tbody></table></div>
{#if review}<Modal {error} label="Prüfung dokumentieren" onclose={() => review = null} busy={saving}><h3>{review.name}</h3><label>Begründung / Nachweis<textarea bind:value={note} maxlength="2000" placeholder="Zweck, geprüfte Rechte und Entscheid…"></textarea></label><div class="cp-actions"><button class="btn btn-secondary" disabled={saving} onclick={() => review = null}>Abbrechen</button><button class="btn btn-primary" onclick={save} disabled={!note.trim() || saving}>Prüfung speichern</button></div></Modal>{/if}
